import{_ as t,o as s,c as a,a2 as n}from"./chunks/framework.D66Xq0Kv.js";const p=JSON.parse('{"title":"Notifications","description":"","frontmatter":{},"headers":[],"relativePath":"guide/notifications.md","filePath":"guide/notifications.md"}'),o={name:"guide/notifications.md"};function i(r,e,d,l,h,c){return s(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h1><p>Orbit tells a Slack or Discord channel, or a list of email addresses, when something needs you: a failed deployment or backup, an incident, a failover, a server going offline, or a <a href="#warnings">warning</a> before something breaks, such as a disk filling up. You do not have to keep the console open to find out.</p><h2 id="slack" tabindex="-1">Adding a Slack channel <a class="header-anchor" href="#slack" aria-label="Permalink to &quot;Adding a Slack channel {#slack}&quot;">​</a></h2><ol><li>In Slack, create an app for your workspace, turn on <strong>Incoming Webhooks</strong> and add a webhook to the channel that should receive the messages. Slack gives you a URL that starts with <code>https://hooks.slack.com/services/</code>.</li><li>In Orbit, open <strong>Settings → Notifications → Add Slack channel</strong>, give the channel a name, paste the URL and choose the events it receives.</li><li>Click <strong>Send test</strong>. Orbit sends one message right away and shows what Slack answered, so a wrong or revoked webhook shows up now and not during an incident.</li></ol><h2 id="discord" tabindex="-1">Adding a Discord channel <a class="header-anchor" href="#discord" aria-label="Permalink to &quot;Adding a Discord channel {#discord}&quot;">​</a></h2><ol><li>In Discord, edit the channel that should receive the messages, open <strong>Integrations → Webhooks</strong> and create a webhook. This needs the <strong>Manage Webhooks</strong> permission. <strong>Copy Webhook URL</strong> gives a URL that starts with <code>https://discord.com/api/webhooks/</code>.</li><li>In Orbit, open <strong>Settings → Notifications → Add Discord channel</strong>, give the channel a name, paste the URL and choose the events it receives.</li><li>Click <strong>Send test</strong>.</li></ol><p>Messages arrive as embeds colored by severity (red for failures, amber for warnings, green when something is resolved), and never mention anyone, so <code>@everyone</code> in a reason cannot ping the channel.</p><h2 id="email-setup" tabindex="-1">Setting up email <a class="header-anchor" href="#email-setup" aria-label="Permalink to &quot;Setting up email {#email-setup}&quot;">​</a></h2><p>Email goes through an SMTP server you already have: your provider&#39;s, or a service such as Amazon SES, Postmark, Mailgun or a mailbox&#39;s own SMTP. Orbit uses one server for every workspace, and only Orbit&#39;s administrator sets it up.</p><ol><li>Open <strong>Settings → Email → Set up email</strong>.</li><li>Enter the server and port, the connection (<strong>STARTTLS</strong>, usually port 587, or <strong>TLS</strong>, usually 465), the user and password, and the address to send from.</li><li>Click <strong>Send a test and save</strong>. Orbit sends a message to you, or to the address you type, with those settings and saves them only if the server accepts it. Otherwise it shows what the server answered, such as <code>535 Authentication credentials invalid</code>.</li></ol><ul><li><strong>The password</strong> is sealed in Orbit&#39;s secret store, never returned and never written to the logs. Leave the field empty when changing the other settings to keep it.</li><li><strong>Unencrypted</strong> connections are only for a server on a private network, and cannot send a user and password.</li><li><strong>Invitations</strong> to a workspace are emailed too once email is set up. See <a href="./members#inviting">Members and roles</a>.</li></ul><h2 id="email" tabindex="-1">Adding an email channel <a class="header-anchor" href="#email" aria-label="Permalink to &quot;Adding an email channel {#email}&quot;">​</a></h2><ol><li>Once email is set up, open <strong>Settings → Notifications → Add email channel</strong>.</li><li>Give it a name, type up to 20 addresses separated by commas or new lines, and choose the events it receives.</li><li>Click <strong>Send test</strong>.</li></ol><p>Messages have a plain text part and a simple HTML part. The subject starts with <code>[Orbit]</code> and names what happened and where, and both parts link to the right page in the console when Orbit has a public HTTPS address.</p><h2 id="channels" tabindex="-1">Channels <a class="header-anchor" href="#channels" aria-label="Permalink to &quot;Channels {#channels}&quot;">​</a></h2><ul><li><strong>Where the URL lives:</strong> it is sealed in Orbit&#39;s secret store, never shown again and never written to the logs or to delivery errors. It travels with <code>orbit backup</code>. To change it, edit the channel and paste a new one.</li><li><strong>Several channels:</strong> add as many as you like, for example one per team, each with its own events.</li><li><strong>Workspaces:</strong> each Orbit workspace has its own channels, and only hears about its own projects. Servers and Orbit updates are shared, so they reach the channels of every workspace that follows them.</li></ul><h2 id="events" tabindex="-1">What Orbit tells you <a class="header-anchor" href="#events" aria-label="Permalink to &quot;What Orbit tells you {#events}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Event</th><th>When</th></tr></thead><tbody><tr><td>A deployment or rollback fails</td><td>A deployment, a rollback, a new application or a preview fails, with the reason the console shows</td></tr><tr><td>A backup fails or cannot be verified</td><td>A backup fails, or is stored but its restore test did not pass</td></tr><tr><td>An incident opens or is resolved</td><td>Orbit opens an incident, such as an application that <a href="./uptime#incidents">stops answering</a>, and again when it is resolved</td></tr><tr><td>A database fails over</td><td>A PostgreSQL replica is promoted after its primary was lost</td></tr><tr><td>A server goes offline</td><td>A server stops answering</td></tr><tr><td>A certificate cannot be issued</td><td>Let&#39;s Encrypt refused or could not issue a domain&#39;s certificate</td></tr><tr><td>WAL archiving fails</td><td>PostgreSQL cannot archive its WAL to the backup storage, so point-in-time recovery stops moving forward</td></tr><tr><td>An Orbit update fails</td><td>An update stopped and needs you</td></tr><tr><td>A server&#39;s Cloudflare Tunnel stays disconnected</td><td>A server&#39;s <a href="./tunnel">tunnel</a> has had no connection to Cloudflare for two minutes</td></tr></tbody></table><p>Each message has a title, the project, environment, service or server it is about, when it happened and why, in the same words the console uses. When Orbit has a public HTTPS address, an <strong>Open in Orbit</strong> button goes straight to the deployment, database, incident or page in question.</p><p><strong>Messages are written in English</strong>, whatever language the console uses.</p><h2 id="warnings" tabindex="-1">Warnings before something breaks <a class="header-anchor" href="#warnings" aria-label="Permalink to &quot;Warnings before something breaks {#warnings}&quot;">​</a></h2><p>Orbit checks every minute for things that are about to break, and lists the open ones under <strong>Warnings</strong> on the Overview. A channel that follows a warning gets one message when it opens and another when it clears, so a disk that stays full does not repeat itself.</p><table tabindex="0"><thead><tr><th>Warning</th><th>Opens when</th><th>Clears when</th></tr></thead><tbody><tr><td>A server&#39;s disk passes 85%</td><td>The disk Kubernetes runs on is at least 85% full for 2 minutes</td><td>It drops below 80%</td></tr><tr><td>A server stays above 90% memory</td><td>Memory in use is at least 90% for 10 minutes</td><td>It drops below 85%</td></tr><tr><td>A server stays above 90% CPU</td><td>CPU is at least 90% busy for 15 minutes</td><td>It drops below 80%</td></tr><tr><td>A database uses 85% of its storage</td><td>The database uses 85% of the storage it was given</td><td>It drops below 80%</td></tr><tr><td>A certificate expires within 14 days</td><td>A domain&#39;s certificate has 14 days or less left. Certificates are renewed 30 days before they expire, so this means renewal is failing</td><td>The certificate is renewed</td></tr><tr><td>A scheduled backup does not run</td><td>An hour after its time, there is no backup for the schedule&#39;s last slot. The message says why Orbit could not start it, when it knows</td><td>A scheduled backup is taken</td></tr></tbody></table><ul><li><strong>The lower clearing mark</strong> keeps a value that hovers around the threshold from opening and clearing again and again.</li><li><strong>A database&#39;s storage size is requested, not enforced:</strong> a database that passes it keeps growing into the server&#39;s disk, so its warning comes before the disk&#39;s.</li><li><strong>Measurements come from Kubernetes on each server.</strong> A server that is offline has no new measurements, so its warnings stay as they were; going offline is its own event.</li><li><strong>New channels</strong> follow every warning. A channel created before warnings existed follows none of them until you tick them in its settings.</li><li>Resolved warnings stay listed for 7 days.</li></ul><h2 id="delivery" tabindex="-1">Repeats and retries <a class="header-anchor" href="#delivery" aria-label="Permalink to &quot;Repeats and retries {#delivery}&quot;">​</a></h2><ul><li><strong>One message per event.</strong> Orbit remembers what it already sent, so a restart does not send it again. After being stopped, it picks up where it left off. If it was stopped for long, it skips what it missed instead of flooding the channel.</li><li><strong>Repeats are grouped.</strong> When the same thing happens again within ten minutes (the same service failing to deploy, the same database failing its backup), the first message goes out at once and the rest arrive as one follow-up at the end of those ten minutes, with how many more times it happened.</li><li><strong>Failed deliveries are retried</strong> after 30 seconds, 2, 10 and 30 minutes and 2 hours. When Slack or Discord says the webhook no longer exists or is not valid, or the email server refuses an address for good (a <code>5xx</code> answer), Orbit stops at once.</li><li><strong>Rate limits delay messages instead of losing them.</strong> Orbit sends a channel&#39;s messages one after the other and follows the limits Discord announces, so a burst waits its turn. When Slack or Discord still answers that it is rate limited, Orbit waits as long as it asks without counting it as a failed attempt, for up to a day.</li><li><strong>Recent messages</strong> in Settings lists the latest deliveries with their status and what Slack or Discord answered. Each channel shows when its last message was sent or why it failed. Deliveries are kept for 30 days.</li></ul>',26)])])}const u=t(o,[["render",i]]);export{p as __pageData,u as default};
